 void ExportModern(){if(!ValidateStudioSave())return;using(var dialog=new DossierSaveFileDialog{Title="Export typed MadCard deck",FileName=FileName.Text+".json",Filter="MadCard deck (*.json)|*.json",DefaultExt="json"})if(dialog.ShowDialog(this)==DialogResult.OK){MakerHelp.Write(dialog.FileName,StudioDeck().ToString());modernStatus.Text="Exported deck: "+dialog.FileName;DossierFeedback.Play("save");}}
 void FindModernField(){var nodes=WalkModern(ObjEditor.Nodes).ToArray();if(nodes.Length==0)return;int start=Array.IndexOf(nodes,ObjEditor.SelectedNode);for(int i=1;i<=nodes.Length;i++){var n=nodes[(start+i+nodes.Length)%nodes.Length];if(n.Text.IndexOf(fieldSearch.Text,StringComparison.OrdinalIgnoreCase)>=0){ObjEditor.SelectedNode=n;n.EnsureVisible();return;}}modernStatus.Text="No matching field or value.";}
 static IEnumerable<TreeNode> WalkModern(TreeNodeCollection nodes){foreach(TreeNode n in nodes){yield return n;foreach(var c in WalkModern(n.Nodes))yield return c;}}
 void ResetModernHistory(){if(historyBusy||ObjEditor.Nodes.Count==0||CardRoot.SelectedItem==null)return;modernHistory.Clear();historyIndex=-1;TrackModernHistory();}
 void TrackModernHistory(){if(historyBusy||Loading||ObjEditor.Nodes.Count==0||CardRoot.SelectedItem==null)return;var state=new JObject{{"Full",SaveObj(ObjEditor.Nodes,true)},{"Sparse",SaveObj(ObjEditor.Nodes)},{"Root",CardRoot.SelectedItem.ToString()},{"Name",FileName.Text}}.ToString();if(historyIndex>=0&&modernHistory[historyIndex]==state)return;if(historyIndex+1<modernHistory.Count)modernHistory.RemoveRange(historyIndex+1,modernHistory.Count-historyIndex-1);modernHistory.Add(state);if(modernHistory.Count>100)modernHistory.RemoveAt(0);historyIndex=modernHistory.Count-1;}
 void TravelModern(int delta){int next=historyIndex+delta;if(next<0||next>=modernHistory.Count)return;var state=JObject.Parse(modernHistory[next]);historyBusy=true;try{Reset();EditedProperties.Clear();Loading=true;CardRoot.SelectedItem=state["Root"].ToString();FileName.Text=state["Name"].ToString();Loading=false;LoadObject(ObjEditor.Nodes,(JObject)state["Full"],ControlScheme,false);MarkEditedNodes((JObject)state["Sparse"]);historyIndex=next;MarkUnsaved(true);DisplayPrice();modernStatus.Text=delta<0?"Change undone":"Change restored";}finally{historyBusy=false;Loading=false;}}
